export interface Frontmatter {
  title: string;
  date?: string;
  tags?: string[];
  draft?: boolean;
  layout?: string;
  [key: string]: unknown;
}

export interface Post {
  slug: string;
  frontmatter: Frontmatter;
  content: string;
  html: string;
  excerpt?: string;
}

export interface SiteData {
  posts: Post[];
  tags: Record<string, Post[]>;
  site: {
    title: string;
    description: string;
    url: string;
  };
}

export interface BuildOptions {
  source: string;
  templates: string;
  output: string;
  drafts: boolean;
  siteTitle: string;
  siteDescription: string;
  siteUrl: string;
}

export interface ServerOptions {
  port: number;
  output: string;
}

import fs from "node:fs/promises";
import path from "node:path";
import matter from "gray-matter";
import { marked } from "marked";
import { markedHighlight } from "marked-highlight";
import hljs from "highlight.js";
import type { Frontmatter, Post } from "./types.js";

marked.use(
  markedHighlight({
    langPrefix: "hljs language-",
    highlight(code: string, lang: string) {
      if (lang && hljs.getLanguage(lang)) {
        return hljs.highlight(code, { language: lang }).value;
      }
      return hljs.highlightAuto(code).value;
    },
  })
);

export function parseFrontmatter(raw: string): { frontmatter: Frontmatter; content: string } {
  const parsed = matter(raw);
  const fm = parsed.data as Frontmatter;
  if (!fm.title) {
    throw new Error("Frontmatter must include a title");
  }
  if (fm.tags && typeof fm.tags === "string") {
    fm.tags = (fm.tags as string).split(",").map((t) => t.trim());
  }
  fm.tags = fm.tags ?? [];
  fm.draft = fm.draft ?? false;
  return { frontmatter: fm, content: parsed.content };
}

export function slugify(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "");
}

export async function loadPosts(sourceDir: string, includeDrafts: boolean): Promise<Post[]> {
  const entries = await fs.readdir(sourceDir, { withFileTypes: true });
  const mdFiles = entries.filter((e) => e.isFile() && e.name.endsWith(".md"));

  const posts: Post[] = [];
  for (const file of mdFiles) {
    const raw = await fs.readFile(path.join(sourceDir, file.name), "utf-8");
    const { frontmatter, content } = parseFrontmatter(raw);
    if (frontmatter.draft && !includeDrafts) continue;
    const html = await marked.parse(content);
    const slug = slugify(frontmatter.title);
    const excerpt = extractExcerpt(html);
    posts.push({ slug, frontmatter, content, html, excerpt });
  }

  posts.sort((a, b) => {
    const da = a.frontmatter.date ? new Date(a.frontmatter.date).getTime() : 0;
    const db = b.frontmatter.date ? new Date(b.frontmatter.date).getTime() : 0;
    return db - da;
  });

  return posts;
}

export function buildTagIndex(posts: Post[]): Record<string, Post[]> {
  const tags: Record<string, Post[]> = {};
  for (const post of posts) {
    for (const tag of post.frontmatter.tags ?? []) {
      if (!tags[tag]) tags[tag] = [];
      tags[tag].push(post);
    }
  }
  return tags;
}

export function formatDate(date: Date): string {
  return date.toISOString().split("T")[0];
}

function extractExcerpt(html: string): string {
  const text = html.replace(/<[^>]+>/g, "");
  return text.length > 200 ? text.slice(0, 200) + "..." : text;
}

import fs from "node:fs/promises";
import path from "node:path";
import Handlebars from "handlebars";
import type { Post, SiteData } from "./types.js";
import { formatDate } from "./frontmatter.js";

export type TemplateSet = {
  post: Handlebars.TemplateDelegate;
  index: Handlebars.TemplateDelegate;
  tag: Handlebars.TemplateDelegate;
  rss: Handlebars.TemplateDelegate;
  reloadScript: string;
};

export async function loadTemplates(templateDir: string): Promise<TemplateSet> {
  const partialsDir = path.join(templateDir, "partials");
  try {
    const partialFiles = await fs.readdir(partialsDir);
    for (const file of partialFiles) {
      if (!file.endsWith(".hbs")) continue;
      const name = path.basename(file, ".hbs");
      const src = await fs.readFile(path.join(partialsDir, file), "utf-8");
      Handlebars.registerPartial(name, src);
    }
  } catch {
    // No partials directory — that is fine
  }

  const readTemplate = async (name: string): Promise<Handlebars.TemplateDelegate> => {
    const src = await fs.readFile(path.join(templateDir, `${name}.hbs`), "utf-8");
    return Handlebars.compile(src);
  };

  const [post, index, tag, rss] = await Promise.all([
    readTemplate("post"),
    readTemplate("index"),
    readTemplate("tag"),
    readTemplate("rss"),
  ]);

  const reloadScript = await fs.readFile(
    path.join(templateDir, "reload.hbs"),
    "utf-8"
  ).catch(() => "");

  registerHelpers();

  return { post, index, tag, rss, reloadScript };
}

function registerHelpers(): void {
  Handlebars.registerHelper("formatDate", (date: string) => {
    return formatDate(new Date(date));
  });

  Handlebars.registerHelper("tagList", (tags: string[]) => {
    return (tags ?? []).join(", ");
  });

  Handlebars.registerHelper("rssDate", (date: string) => {
    return new Date(date).toUTCString();
  });
}

export function renderIndex(template: Handlebars.TemplateDelegate, data: SiteData): string {
  return template(data, { allowProtoPropertiesByDefault: true });
}

import type { Post, SiteData } from "./types.js";

export function generateRssXml(data: SiteData, rssTemplate: (ctx: object) => string): string {
  return rssTemplate(data);
}

export function buildRssData(data: SiteData, template: (ctx: object) => string): string {
  return template(data);
}

import fs from "node:fs/promises";
import path from "node:path";
import type { BuildOptions, Post, SiteData, Frontmatter } from "./types.js";
import { loadPosts, buildTagIndex, formatDate } from "./frontmatter.js";
import { loadTemplates, renderIndex } from "./render.js";
import { buildRssData } from "./rss.js";

export async function build(options: BuildOptions): Promise<void> {
  await fs.rm(options.output, { recursive: true, force: true });
  await fs.mkdir(options.output, { recursive: true });

  const posts = await loadPosts(options.source, options.drafts);
  const tags = buildTagIndex(posts);

  const siteData: SiteData = {
    posts,
    tags,
    site: {
      title: options.siteTitle,
      description: options.siteDescription,
      url: options.siteUrl,
    },
  };

  const templates = await loadTemplates(options.templates);

  for (const post of posts) {
    const html = layoutWrap(
      templates.post({ ...post, site: siteData.site }, { allowProtoPropertiesByDefault: true }),
      templates.reloadScript,
      post.frontmatter
    );
    await writePage(options.output, post.slug, html);
  }

  const indexHtml = layoutWrap(
    templates.index(siteData, { allowProtoPropertiesByDefault: true }),
    templates.reloadScript,
    { title: options.siteTitle }
  );
  await fs.writeFile(path.join(options.output, "index.html"), indexHtml);

  // Tag pages
  const tagsDir = path.join(options.output, "tags");
  await fs.mkdir(tagsDir, { recursive: true });
  for (const [tag, tagPosts] of Object.entries(tags)) {
    const tagHtml = layoutWrap(
      templates.tag(
        { tag, posts: tagPosts, site: siteData.site },
        { allowProtoPropertiesByDefault: true }
      ),
      templates.reloadScript,
      { title: `Tag: ${tag}` }
    );
    await fs.writeFile(path.join(tagsDir, `${tag}.html`), tagHtml);
  }

  // RSS
  const rssXml = templates.rss(siteData, { allowProtoPropertiesByDefault: true });
  await fs.writeFile(path.join(options.output, "feed.xml"), `<?xml version="1.0" encoding="UTF-8"?>\n${rssXml}`);

  // Copy static assets if present
  const assetsSrc = path.join(options.source, "assets");
  try {
    const assets = await fs.readdir(assetsSrc);
    const assetsDst = path.join(options.output, "assets");
    await fs.mkdir(assetsDst, { recursive: true });
    for (const asset of assets) {
      await fs.cp(path.join(assetsSrc, asset), path.join(assetsDst, asset), { recursive: true });
    }
  } catch {
    // No assets dir — fine
  }

  console.log(`Built ${posts.length} posts, ${Object.keys(tags).length} tag pages to ${options.output}`);
}

function layoutWrap(inner: string, reloadScript: string, fm: Frontmatter): string {
  const scriptTag = reloadScript ? `<script>${reloadScript}</script>` : "";
  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>${fm.title ?? ""}</title>
</head>
<body>
${inner}
${scriptTag}
</body>
</html>`;
}

async function writePage(output: string, slug: string, html: string): Promise<void> {
  const out = path.join(output, `${slug}.html`);
  await fs.writeFile(out, html);
}

import fs from "node:fs/promises";
import path from "node:path";
import Handlebars from "handlebars";
import { formatDate } from "./frontmatter.js";

export interface Templates {
  layout: Handlebars.TemplateDelegate | null;
  post: Handlebars.TemplateDelegate;
  index: Handlebars.TemplateDelegate;
  tag: Handlebars.TemplateDelegate;
  rss: Handlebars.TemplateDelegate;
  reloadScript: string;
}

export async function loadTemplates(templateDir: string): Promise<Templates> {
  const partialsDir = path.join(templateDir, "partials");
  try {
    const partialFiles = await fs.readdir(partialsDir);
    for (const file of partialFiles) {
      if (!file.endsWith(".hbs")) continue;
      const name = path.basename(file, ".hbs");
      const src = await fs.readFile(path.join(partialsDir, file), "utf-8");
      Handlebars.registerPartial(name, src);
    }
  } catch {
    // No partials directory
  }

  registerHelpers();

  const readTemplate = async (name: string): Promise<Handlebars.TemplateDelegate> => {
    const src = await fs.readFile(path.join(templateDir, `${name}.hbs`), "utf-8");
    return Handlebars.compile(src);
  };

  const [post, index, tag, rss] = await Promise.all([
    readTemplate("post"),
    readTemplate("index"),
    readTemplate("tag"),
    readTemplate("rss"),
  ]);

  let layout: Handlebars.TemplateDelegate | null = null;
  try {
    layout = await readTemplate("layout");
  } catch {
    // No layout template is ok
  }

  const reloadScript = await fs
    .readFile(path.join(templateDir, "reload.hbs"), "utf-8")
    .catch(() => "");

  return { layout, post, index, tag, rss, reloadScript };
}

function registerHelpers(): void {
  Handlebars.registerHelper("formatDate", (date: unknown) => {
    if (typeof date !== "string" && !(date instanceof Date)) return "";
    return formatDate(new Date(date as string));
  });

  Handlebars.registerHelper("tagList", (tags: string[] | undefined) => {
    return (tags ?? []).join(", ");
  });

  Handlebars.registerHelper("rssDate", (date: unknown) => {
    if (typeof date !== "string" && !(date instanceof Date)) return "";
    return new Date(date as string).toUTCString();
  });
}

export function applyLayout(
  templates: Templates,
  body: string,
  context: Record<string, unknown>
): string {
  const scriptTag = templates.reloadScript ? `<script>${templates.reloadScript}</script>` : "";

  if (templates.layout) {
    const fullHtml = templates.layout(
      { ...context, body, reloadScript: scriptTag },
      { allowProtoPropertiesByDefault: true }
    );
    return fullHtml;
  }

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>${context.title ?? ""}</title>
</head>
<body>
${body}
${scriptTag}
</body>
</html>`;
}

import fs from "node:fs/promises";
import path from "node:path";
import type { BuildOptions, Post, SiteData } from "./types.js";
import { loadPosts, buildTagIndex } from "./frontmatter.js";
import { loadTemplates, applyLayout } from "./render.js";

export async function build(options: BuildOptions): Promise<void> {
  await fs.rm(options.output, { recursive: true, force: true });
  await fs.mkdir(options.output, { recursive: true });

  const posts = await loadPosts(options.source, options.drafts);
  const tags = buildTagIndex(posts);

  const siteData: SiteData = {
    posts,
    tags,
    site: {
      title: options.siteTitle,
      description: options.siteDescription,
      url: options.siteUrl,
    },
  };

  const tpl = await loadTemplates(options.templates);

  for (const post of posts) {
    const body = tpl.post(
      { ...post, site: siteData.site },
      { allowProtoPropertiesByDefault: true }
    );
    const html = applyLayout(tpl, body, { title: post.frontmatter.title });
    await writePage(options.output, post.slug, html);
  }

  const indexBody = tpl.index(siteData, { allowProtoPropertiesByDefault: true });
  const indexHtml = applyLayout(tpl, indexBody, { title: options.siteTitle });
  await fs.writeFile(path.join(options.output, "index.html"), indexHtml);

  const tagsDir = path.join(options.output, "tags");
  await fs.mkdir(tagsDir, { recursive: true });
  for (const [tag, tagPosts] of Object.entries(tags)) {
    const tagBody = tpl.tag(
      { tag, posts: tagPosts, site: siteData.site },
      { allowProtoPropertiesByDefault: true }
    );
    const tagHtml = applyLayout(tpl, tagBody, { title: `Tag: ${tag}` });
    await fs.writeFile(path.join(tagsDir, `${tag}.html`), tagHtml);
  }

  const rssBody = tpl.rss(siteData, { allowProtoPropertiesByDefault: true });
  await fs.writeFile(
    path.join(options.output, "feed.xml"),
    `<?xml version="1.0" encoding="UTF-8"?>\n${rssBody}`
  );

  const assetsSrc = path.join(options.source, "assets");
  try {
    const assets = await fs.readdir(assetsSrc);
    const assetsDst = path.join(options.output, "assets");
    await fs.mkdir(assetsDst, { recursive: true });
    for (const asset of assets) {
      await fs.cp(path.join(assetsSrc, asset), path.join(assetsDst, asset), { recursive: true });
    }
  } catch {
    // No assets dir
  }

  console.log(
    `Built ${posts.length} posts, ${Object.keys(tags).length} tag pages to ${options.output}`
  );
}

async function writePage(output: string, slug: string, html: string): Promise<void> {
  const out = path.join(output, `${slug}.html`);
  await fs.writeFile(out, html);
}

import http from "node:http";
import fs from "node:fs/promises";
import path from "node:path";
import { WebSocketServer, WebSocket } from "ws";
import chokidar from "chokidar";
import type { ServerOptions } from "./types.js";
import { build } from "./build.js";
import type { BuildOptions } from "./types.js";

export function startDevServer(serverOptions: ServerOptions, buildOptions: BuildOptions): void {
  let clients: WebSocket[] = [];

  const server = http.createServer(async (req, res) => {
    const url = req.url === "/" ? "/index.html" : req.url ?? "/index.html";
    const filePath = path.join(buildOptions.output, url);

    try {
      const content = await fs.readFile(filePath);
      const ext = path.extname(filePath);
      const mime: Record<string, string> = {
        ".html": "text/html",
        ".css": "text/css",
        ".js": "application/javascript",
        ".xml": "application/xml",
        ".png": "image/png",
        ".jpg": "image/jpeg",
        ".svg": "image/svg+xml",
      };
      res.writeHead(200, { "Content-Type": mime[ext] ?? "text/plain" });
      res.end(content);
    } catch {
      res.writeHead(404);
      res.end("Not Found");
    }
  });

  const wss = new WebSocketServer({ server });

  wss.on("connection", (ws) => {
    clients.push(ws);
    ws.on("close", () => {
      clients = clients.filter((c) => c !== ws);
    });
  });

  const watcher = chokidar.watch(
    [buildOptions.source, buildOptions.templates],
    { ignoreInitial: true }
  );

  const debouncedRebuild = debounce(async () => {
    try {
      await build(buildOptions);
      const data = JSON.stringify({ type: "reload" });
      for (const client of clients) {
        if (client.readyState === WebSocket.OPEN) {
          client.send(data);
        }
      }
      console.log("Rebuilt and signaled reload");
    } catch (err) {
      console.error("Build error:", err);
    }
  }, 300);

  watcher.on("all", () => {
    debouncedRebuild();
  });

  server.listen(serverOptions.port, () => {
    console.log(`Dev server running at http://localhost:${serverOptions.port}`);
  });
}

function debounce(fn: () => void, ms: number): () => void {
  let timer: ReturnType<typeof setTimeout> | null = null;
  return () => {
    if (timer) clearTimeout(timer);
    timer = setTimeout(fn, ms);
  };
}

#!/usr/bin/env node
import { Command } from "commander";
import { build } from "./build.js";
import { startDevServer } from "./server.js";
import type { BuildOptions, ServerOptions } from "./types.js";

const program = new Command();

program
  .name("staticsmith")
  .description("Static site generator: Markdown + Handlebars → HTML")
  .version("1.0.0");

program
  .command("build")
  .description("Build the static site")
  .option("-s, --source <dir>", "Source directory of Markdown files", "content")
  .option("-t, --templates <dir>", "Template directory of Handlebars files", "templates")
  .option("-o, --output <dir>", "Output directory for generated HTML", "public")
  .option("--drafts", "Include draft posts", false)
  .option("--site-title <title>", "Site title", "My Site")
  .option("--site-description <desc>", "Site description", "A static site")
  .option("--site-url <url>", "Site base URL", "http://localhost:3000")
  .action(async (opts) => {
    const options: BuildOptions = {
      source: opts.source,
      templates: opts.templates,
      output: opts.output,
      drafts: opts.drafts,
      siteTitle: opts.siteTitle,
      siteDescription: opts.siteDescription,
      siteUrl: opts.siteUrl,
    };
    await build(options);
  });

program
  .command("serve")
  .description("Start dev server with live reload")
  .option("-s, --source <dir>", "Source directory of Markdown files", "content")
  .option("-t, --templates <dir>", "Template directory of Handlebars files", "templates")
  .option("-o, --output <dir>", "Output directory for generated HTML", "public")
  .option("-p, --port <number>", "Port to listen on", "3000")
  .option("--drafts", "Include draft posts", false)
  .option("--site-title <title>", "Site title", "My Site")
  .option("--site-description <desc>", "Site description", "A static site")
  .option("--site-url <url>", "Site base URL", "http://localhost:3000")
  .action(async (opts) => {
    const buildOptions: BuildOptions = {
      source: opts.source,
      templates: opts.templates,
      output: opts.output,
      drafts: opts.drafts,
      siteTitle: opts.siteTitle,
      siteDescription: opts.siteDescription,
      siteUrl: opts.siteUrl,
    };

    // Build first, then serve
    await build(buildOptions);

    const serverOptions: ServerOptions = {
      port: parseInt(opts.port, 10),
      output: opts.output,
    };

    startDevServer(serverOptions, buildOptions);
  });

program.parse();

import type { SiteData } from "./types.js";
import { formatDate } from "./frontmatter.js";

export function rssXml(data: SiteData): string {
  const items = data.posts
    .slice(0, 20)
    .map(
      (p) => `    <item>
      <title>${esc(p.frontmatter.title)}</title>
      <link>${esc(data.site.url)}/${esc(p.slug)}.html</link>
      <description>${esc(p.excerpt ?? "")}</description>
      <pubDate>${p.frontmatter.date ? new Date(p.frontmatter.date).toUTCString() : ""}</pubDate>
      <guid>${esc(data.site.url)}/${esc(p.slug)}.html</guid>
    </item>`
    )
    .join("\n");

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>${esc(data.site.title)}</title>
    <description>${esc(data.site.description)}</description>
    <link>${esc(data.site.url)}</link>
    <atom:link href="${esc(data.site.url)}/feed.xml" rel="self" type="application/rss+xml"/>
    <lastBuildDate>${new Date().toUTCString()}</lastBuildDate>
${items}
  </channel>
</rss>`;
}

function esc(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

import fs from "node:fs/promises";
import path from "node:path";
import type { BuildOptions, Post, SiteData } from "./types.js";
import { loadPosts, buildTagIndex } from "./frontmatter.js";
import { loadTemplates, applyLayout } from "./render.js";
import { rssXml } from "./rss.js";

export async function build(options: BuildOptions): Promise<void> {
  await fs.rm(options.output, { recursive: true, force: true });
  await fs.mkdir(options.output, { recursive: true });

  const posts = await loadPosts(options.source, options.drafts);
  const tags = buildTagIndex(posts);

  const siteData: SiteData = {
    posts,
    tags,
    site: {
      title: options.siteTitle,
      description: options.siteDescription,
      url: options.siteUrl,
    },
  };

  const tpl = await loadTemplates(options.templates);

  for (const post of posts) {
    const body = tpl.post(
      { ...post, site: siteData.site },
      { allowProtoPropertiesByDefault: true }
    );
    const html = applyLayout(tpl, body, { title: post.frontmatter.title });
    await writePage(options.output, post.slug, html);
  }

  const indexBody = tpl.index(siteData, { allowProtoPropertiesByDefault: true });
  const indexHtml = applyLayout(tpl, indexBody, { title: options.siteTitle });
  await fs.writeFile(path.join(options.output, "index.html"), indexHtml);

  const tagsDir = path.join(options.output, "tags");
  await fs.mkdir(tagsDir, { recursive: true });
  for (const [tag, tagPosts] of Object.entries(tags)) {
    const tagBody = tpl.tag(
      { tag, posts: tagPosts, site: siteData.site },
      { allowProtoPropertiesByDefault: true }
    );
    const tagHtml = applyLayout(tpl, tagBody, { title: `Tag: ${tag}` });
    await fs.writeFile(path.join(tagsDir, `${tag}.html`), tagHtml);
  }

  // RSS: use template if available, otherwise programmatic
  const feed = tpl.rss
    ? tpl.rss(siteData, { allowProtoPropertiesByDefault: true })
    : rssXml(siteData);
  await fs.writeFile(path.join(options.output, "feed.xml"), feed);

  const assetsSrc = path.join(options.source, "assets");
  try {
    const assets = await fs.readdir(assetsSrc);
    const assetsDst = path.join(options.output, "assets");
    await fs.mkdir(assetsDst, { recursive: true });
    for (const asset of assets) {
      await fs.cp(path.join(assetsSrc, asset), path.join(assetsDst, asset), { recursive: true });
    }
  } catch {
    // No assets dir
  }

  console.log(
    `Built ${posts.length} posts, ${Object.keys(tags).length} tag pages to ${options.output}`
  );
}

async function writePage(output: string, slug: string, html: string): Promise<void> {
  const out = path.join(output, `${slug}.html`);
  await fs.writeFile(out, html);
}

import fs from "node:fs/promises";
import path from "node:path";
import Handlebars from "handlebars";
import { formatDate } from "./frontmatter.js";

export interface Templates {
  layout: Handlebars.TemplateDelegate | null;
  post: Handlebars.TemplateDelegate;
  index: Handlebars.TemplateDelegate;
  tag: Handlebars.TemplateDelegate;
  rss: Handlebars.TemplateDelegate | null;
  reloadScript: string;
}

export async function loadTemplates(templateDir: string): Promise<Templates> {
  const partialsDir = path.join(templateDir, "partials");
  try {
    const partialFiles = await fs.readdir(partialsDir);
    for (const file of partialFiles) {
      if (!file.endsWith(".hbs")) continue;
      const name = path.basename(file, ".hbs");
      const src = await fs.readFile(path.join(partialsDir, file), "utf-8");
      Handlebars.registerPartial(name, src);
    }
  } catch {
    // No partials directory
  }

  registerHelpers();

  const readTemplate = async (name: string): Promise<Handlebars.TemplateDelegate> => {
    const src = await fs.readFile(path.join(templateDir, `${name}.hbs`), "utf-8");
    return Handlebars.compile(src);
  };

  const optTemplate = async (name: string): Promise<Handlebars.TemplateDelegate | null> => {
    try {
      return await readTemplate(name);
    } catch {
      return null;
    }
  };

  const [post, index, tag, layout, rss] = await Promise.all([
    readTemplate("post"),
    readTemplate("index"),
    readTemplate("tag"),
    optTemplate("layout"),
    optTemplate("rss"),
  ]);

  const reloadScript = await fs
    .readFile(path.join(templateDir, "reload.hbs"), "utf-8")
    .catch(() => "");

  return { layout, post, index, tag, rss, reloadScript };
}

function registerHelpers(): void {
  Handlebars.registerHelper("formatDate", (date: unknown) => {
    if (typeof date !== "string" && !(date instanceof Date)) return "";
    return formatDate(new Date(date as string));
  });

  Handlebars.registerHelper("tagList", (tags: string[] | undefined) => {
    return (tags ?? []).join(", ");
  });

  Handlebars.registerHelper("rssDate", (date: unknown) => {
    if (typeof date !== "string" && !(date instanceof Date)) return "";
    return new Date(date as string).toUTCString();
  });
}

export function applyLayout(
  templates: Templates,
  body: string,
  context: Record<string, unknown>
): string {
  const scriptTag = templates.reloadScript ? `<script>${templates.reloadScript}</script>` : "";

  if (templates.layout) {
    return templates.layout(
      { ...context, body, reloadScript: scriptTag },
      { allowProtoPropertiesByDefault: true }
    );
  }

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>${context.title ?? ""}</title>
</head>
<body>
${body}
${scriptTag}
</body>
</html>`;
}

