    tmpOut = await fs.mkdtemp(path.join(os.tmpdir(), "ssg-out3-"));
    const sourceDir = path.join(projectRoot, "tests", "fixtures", "source");
    const tplDir = path.join(projectRoot, "tests", "fixtures", "templates");

