      { allowProtoPropertiesByDefault: true }
    );
  }

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>${context.title ?? ""}</title>
</head>
<body>
${body}
${scriptTag}
</body>
</html>`;
}

